import { plural, type LocalePack } from '../index';

/**
 * Pakiet języka polskiego (pl-PL).
 *
 * Wytyczne:
 * - Naturalny, zwięzły język interfejsu (np. „Eksportuj”, „Anuluj”, „Synchronizuj”)
 * - Poprawne formy liczebników: plural(n, { one: '...', few: '...', many: '...', other: '...' })
 * - Zachowanie terminologii technicznej, jednostek, kluczy CLI/MCP i tokenów
 * - Brak zmyślonych danych dla brakujących próbek
 */

type Params = Record<string, unknown>;
const str = (value: unknown): string => (typeof value === 'string' || typeof value === 'number' ? String(value) : '');
const day = (value: unknown): string => str(value);
const activity = (value: unknown): string => str(value);

